clientlearned
.pro中+network
QTcpsocket类::connetToHost
跳转方式，创建新的指针（指针在堆上，实例在栈上）
ba.append(ui-&gt;lineEdit-&gt;text().toUtf8()); QByteArray加QString字符串的方法



code#include &quot;widget.h&quot;#include &quot;ui_widget.h&quot;#include &lt;QMessageBox&gt;#include&quot;chat.h&quot;Widget::Widget(QWidget *parent)    : QWidget(parent)    , ui(new Ui::Widget)&#123;    ui-&gt;setupUi(this);    socket=new QTcpSocket;&#125;Widget::~Widget()&#123;    delete ui;&#125;void Widget::on_cancelButton_clicked()&#123;    this-&gt;close();&#125;void Widget::on_connectButton_clicked()&#123;    //ip port    QString IP=ui-&gt;ipLine-&gt;text();    QString port=ui-&gt;portLine-&gt;text();    //connect    socket-&gt;connectToHost(QHostAddress(IP),port.toShort());    //whether success    connect(socket,&amp;QTcpSocket::connected,[this]()&#123;        QMessageBox::information(this,&quot;连接提示&quot;,&quot;连接服务器成功&quot;);        this-&gt;hide();        Chat *C=new Chat(socket);        C-&gt;show();    &#125;);    connect(socket,&amp;QTcpSocket::disconnected,[this]()&#123;        QMessageBox::warning(this,&quot;连接提示&quot;,&quot;连接异常，网络断开&quot;);    &#125;);&#125;

#include &quot;chat.h&quot;#include &quot;ui_chat.h&quot;Chat::Chat(QTcpSocket *s,QWidget *parent)    : QWidget(parent)    , ui(new Ui::Chat)&#123;    ui-&gt;setupUi(this);    socket=s;&#125;Chat::~Chat()&#123;    delete ui;&#125;void Chat::on_clearButton_clicked()&#123;    ui-&gt;lineEdit-&gt;clear();&#125;void Chat::on_sendButton_clicked()&#123;    QByteArray ba;    ba.append(ui-&gt;lineEdit-&gt;text().toUtf8());    ui-&gt;lineEdit-&gt;text();    socket-&gt;write(ba);&#125;

server
线程的创建 继承QThread -&gt;start启动
信号量 emit+signals声明 发送信号


code#include &quot;mythread.h&quot;myThread::myThread(QTcpSocket *s)&#123;    socket=s;&#125;void myThread::run()&#123;    connect(socket,&amp;QTcpSocket::readyRead,this,&amp;myThread::clientInfoSlot);&#125;void myThread::clientInfoSlot()&#123;    // socket-&gt;readAll();    QByteArray ba=socket-&gt;readAll();    emit sendToWidget(ba);&#125;

#include &quot;widget.h&quot;#include &quot;ui_widget.h&quot;Widget::Widget(QWidget *parent)    : QWidget(parent)    , ui(new Ui::Widget)&#123;    ui-&gt;setupUi(this);    server=new QTcpServer;    server-&gt;listen(QHostAddress::AnyIPv4,PORT);    connect(server,&amp;QTcpServer::newConnection,this,&amp;Widget::newClientHandler);&#125;Widget::~Widget()&#123;    delete ui;&#125;void Widget::newClientHandler()&#123;    QTcpSocket *socket=server-&gt;nextPendingConnection();    // socket-&gt;peerAddress();    // socket-&gt;peerPort();    ui-&gt;ipLineEdit-&gt;setText(socket-&gt;peerAddress().toString());    ui-&gt;portLineEdit-&gt;setText(QString::number(socket-&gt;peerPort()));    // connect(socket,&amp;QTcpSocket::readyRead,this,&amp;Widget::clientInfoSlot);    //启动线程    myThread *t=new myThread(socket);    t-&gt;start();    connect(t,&amp;myThread::sendToWidget,this,&amp;Widget::threadSlot);&#125;// void Widget::clientInfoSlot()&#123;//     QTcpSocket *s = (QTcpSocket*)sender();//获取信号发出者//     ui-&gt;mainLineEdit-&gt;setText(QString(s-&gt;readAll()));// &#125;void Widget::threadSlot(QByteArray b)&#123;    ui-&gt;mainLineEdit-&gt;setText(QString(b));&#125;

learned
重载QPaintEvent::paintEvent, 使之能够加载图片
snprintf基于printf处理字符串，QString中.arg()可以模拟，注意参数是%num;
connect调用的函数必须加&amp;
Qpixmap::scale()用于调整大小
Widget::update直接更新窗口
透明窗口、透明背景、与移动


this-&gt;setWindowFlag(Qt::FramelessWindowHint);     // 去除窗口边框    this-&gt;setAttribute(Qt::WA_TranslucentBackground); // 背景透明    this-&gt;installEventFilter(new DragFilter);


最小化系统图标的使用

QSystemTrayIcon sysTray(QIcon(&quot;:/pic/image/icon.png&quot;),&amp;w);    QMenu menu;    auto showAct=new QAction(&quot;show&quot;,&amp;sysTray);    auto exitAct=new QAction(&quot;exit&quot;,&amp;sysTray);    QObject::connect(showAct,&amp;QAction::triggered,&amp;w,[&amp;]()&#123;        w.setVisible(true);    &#125;);    QObject::connect(exitAct,&amp;QAction::triggered,&amp;a,[&amp;]()&#123;        QApplication::quit();    &#125;);    menu.addAction(showAct);    menu.addAction(exitAct);    sysTray.setContextMenu(&amp;menu);    sysTray.show();


widget::setVisible暂时关闭窗口
QUrl更安全的跨平台链接
Q_ENUM_NS(RoleAct)&#x2F;&#x2F;注册枚举

new_learn拖动窗口的内置函数实现
if (w-&gt;windowHandle())                &#123;                    w-&gt;windowHandle()-&gt;startSystemMove();                    return true;                &#125;
code#include &quot;widget.h&quot;#include &lt;QPixmap&gt;#include &lt;QDebug&gt;#include &lt;Qcursor&gt;#include &lt;QMetaEnum&gt;Widget::Widget(QWidget *parent)    : QWidget(parent),    timer(new QTimer(this)),//自动析构    menu(new QMenu(this))&#123;    this-&gt;setWindowFlag(Qt::FramelessWindowHint);//去除窗口边框    this-&gt;setAttribute(Qt::WA_TranslucentBackground);//背景透明    this-&gt;installEventFilter(new DragFilter);    connect(timer,&amp;QTimer::timeout,this,[this]()&#123;        static int index=0;//记录显示动作的图片索引        auto paths=this-&gt;action_map.value(this-&gt;cur_role_act);        this-&gt;cur_role_pix=paths[index++%paths.size()];        //paintEvent()会递归调用        this-&gt;update();    &#125;);    loadRoleActRes();    showActAnimation(RoleAct::SayHello);    initMennu();&#125;Widget::~Widget() &#123;&#125;void Widget::showActAnimation(RoleAct k)&#123;    timer-&gt;stop();    this-&gt;cur_role_act=k;    timer-&gt;start(500);&#125;void Widget::onMenuTriggered(QAction *action)&#123;    QMetaEnum me=QMetaEnum::fromType&lt;RoleAct&gt;();    bool ok;    int k=me.keyToValue(action-&gt;text().toStdString().c_str(),&amp;ok);    if(!ok)return;    showActAnimation(static_cast&lt;RoleAct&gt;(k));&#125;void Widget::paintEvent(QPaintEvent *event)&#123;    QPainter painter(this);    QPixmap pix;    // qDebug()&lt;&lt;&quot;pix path:&quot;&lt;&lt;this-&gt;cur_role_pix.toLocalFile();    pix.load(this-&gt;cur_role_pix.toLocalFile());    int targetWidth = 200;  // 你想要的宽    int targetHeight = 150; // 你想要的高    pix = pix.scaled(targetWidth, targetHeight, Qt::KeepAspectRatio, Qt::SmoothTransformation);    painter.drawPixmap(0,0,pix);&#125;void Widget::contextMenuEvent(QContextMenuEvent *event)&#123;    this-&gt;menu-&gt;popup(QCursor::pos());&#125;void Widget::loadRoleActRes()&#123;    auto addRes=[this](RoleAct k,QString path,int count)    &#123;        QList&lt;QUrl&gt;paths;        char buf[260];//path最长255        for(int i=0;i&lt;count;++i)        &#123;            memset(buf,0,sizeof(buf));            sprintf_s(buf,path.toStdString().c_str(),i);            paths.append(QUrl::fromLocalFile(buf));        &#125;        action_map.insert(k,paths);        // qDebug()&lt;&lt;paths[1];    &#125;;    addRes(RoleAct::SayHello,&quot;:/pic/image/sayHello/sayHello%d.png&quot;,4);    addRes(RoleAct::Sleep,&quot;:/%d.png&quot;,32);    addRes(RoleAct::Swing,&quot;:/%d.png&quot;,11);&#125;void Widget::initMennu()&#123;    menu-&gt;addAction(&quot;SayHello&quot;);    menu-&gt;addAction(&quot;Sleep&quot;);    menu-&gt;addAction(&quot;Swing&quot;);    QAction* act=new QAction(&quot;Hide&quot;);    connect(act,&amp;QAction::triggered,this,[this]()&#123;        this-&gt;setVisible(false);    &#125;);    menu-&gt;addAction(act);    connect(this-&gt;menu,&amp;QMenu::triggered,this,Widget::onMenuTriggered);&#125;

#ifndef WIDGET_H#define WIDGET_H#include &lt;QWidget&gt;#include &lt;QPaintEvent&gt;#include &lt;QPainter&gt;#include &lt;QEvent&gt;#include &lt;QMouseEvent&gt;#include &lt;QContextMenuEvent&gt;#include &lt;QMenu&gt;#include&lt;QMap&gt;#include&lt;QList&gt;#include&lt;QUrl&gt;#include&lt;QTimer&gt;namespace Act&#123;    Q_NAMESPACEenum RoleAct&#123;        SayHello,        Swing,        Sleep,    &#125;;    Q_ENUM_NS(RoleAct)//注册枚举&#125;    using namespace Act;class Widget : public QWidget&#123;    Q_OBJECTpublic:    Widget(QWidget *parent = nullptr);    ~Widget();public:    void showActAnimation(RoleAct k);public slots:    void onMenuTriggered(QAction *action);protected:    void paintEvent(QPaintEvent *event)override;    void contextMenuEvent(QContextMenuEvent*event)override;private:    void loadRoleActRes();    void initMennu();private:    QMap&lt;RoleAct,QList&lt;QUrl&gt;&gt;action_map;    QTimer* timer;    RoleAct cur_role_act;    QUrl cur_role_pix;    QMenu* menu;&#125;;class DragFilter:public QObject&#123;public:    bool eventFilter(QObject*obj,QEvent*event)    &#123;        auto w=dynamic_cast&lt;QWidget*&gt;(obj);        if(!w)            return false;        if(event-&gt;type()==QEvent::MouseButtonPress)        &#123;            auto e =dynamic_cast&lt;QMouseEvent*&gt;(event);            if(e)            &#123;                pos=e-&gt;pos();            &#125;        &#125;        else if(event-&gt;type()==QEvent::MouseMove)        &#123;            auto e =dynamic_cast&lt;QMouseEvent*&gt;(event);            if(e)            &#123;                if(e-&gt;buttons()&amp;Qt::MouseButton::LeftButton)                &#123;                    w-&gt;move(e-&gt;globalPosition().toPoint()-pos);                &#125;            &#125;        &#125;        return QObject::eventFilter(obj,event);    &#125;private:    QPoint pos;&#125;;#endif // WIDGET_H

#include &quot;widget.h&quot;#include &lt;QApplication&gt;#include &lt;QSystemTrayIcon&gt;//系统菜单托盘int main(int argc, char *argv[])&#123;    QApplication a(argc, argv);    Widget w;    QSystemTrayIcon sysTray(QIcon(&quot;:/pic/image/icon.png&quot;),&amp;w);    QMenu menu;    auto showAct=new QAction(&quot;show&quot;,&amp;sysTray);    auto exitAct=new QAction(&quot;exit&quot;,&amp;sysTray);    QObject::connect(showAct,&amp;QAction::triggered,[&amp;]()&#123;        w.setVisible(true);    &#125;);    QObject::connect(exitAct,&amp;QAction::triggered,[&amp;]()&#123;        QApplication::quit();    &#125;);    menu.addAction(showAct);    menu.addAction(exitAct);    sysTray.setContextMenu(&amp;menu);    sysTray.show();    w.show();    return a.exec();&#125;

本地learned
.pro +sql
QSqlDatabase::addDatabase(“NAME”)加载数据库
QSqlquery::exec执行sql命令，返回true或false
QString的拼接 .arg()

QString sql=QString(&quot;insert into student values (%1,&#x27;%2&#x27;,&#x27;%3&#x27;);)&quot;).arg(id).arg(name).arg(birthday);

code#include &quot;widget.h&quot;#include &quot;ui_widget.h&quot;#include &lt;QMessageBox&gt;#include &lt;QSqlQuery&gt;Widget::Widget(QWidget *parent)    : QWidget(parent)    , ui(new Ui::Widget)&#123;    ui-&gt;setupUi(this);    db = QSqlDatabase::addDatabase(&quot;QMYSQL&quot;);//加载MySQL数据库驱动    db.setDatabaseName(&quot;mydatabase&quot;);    db.setHostName(&quot;localhost&quot;);    db.setUserName(&quot;root&quot;);    db.setPassword(&quot;ljn20040118@@&quot;);    qDebug()&lt;&lt;QSqlDatabase::drivers();    if(db.open())    &#123;        QMessageBox::information(this,&quot;连接提示&quot;,&quot;连接成功&quot;);    &#125;    else&#123;        QMessageBox::warning(this,&quot;连接提示&quot;,&quot;连接失败&quot;);    &#125;&#125;Widget::~Widget()&#123;    delete ui;&#125;void Widget::on_insertButton_clicked()&#123;    QString id = ui-&gt;numberEdit-&gt;text();    QString name = ui-&gt;numberEdit-&gt;text();    QString birthday = ui-&gt;birthdayEdit-&gt;text();    QString sql=QString(&quot;insert into student values (%1,&#x27;%2&#x27;,&#x27;%3&#x27;);)&quot;).arg(id).arg(name).arg(birthday);    QSqlQuery query;    if(query.exec(sql))    &#123;        QMessageBox::information(this,&quot;插入提示&quot;,&quot;插入成功&quot;);    &#125;    else    &#123;        QMessageBox::warning(this,&quot;插入提示&quot;,&quot;插入失败&quot;);    &#125;&#125;void Widget::on_findButton_clicked()&#123;    QSqlQuery query;    query.exec(&quot;select * from student&quot;);    while(query.next())    &#123;        qDebug()&lt;&lt;query.value(0);    &#125;&#125;

网络learnedQSqlTableModel::-&gt;select方法+QTableView组件-&gt;setModel 方便显示
code#include &quot;widget.h&quot;#include &quot;ui_widget.h&quot;#include &lt;QMessageBox&gt;Widget::Widget(QWidget *parent)    : QWidget(parent)    , ui(new Ui::Widget)&#123;    ui-&gt;setupUi(this);    QSqlDatabase db=QSqlDatabase::addDatabase(&quot;QMYSQL&quot;);    db.setHostName(&quot;192.168.217.129&quot;);    db.setDatabaseName(&quot;mydatabase&quot;);    db.setUserName(&quot;test0&quot;);    db.setPassword(&quot;ljn20040118LJN@@&quot;);    if(db.open())    &#123;        QMessageBox::information(this,&quot;连接提示&quot;,&quot;连接成功&quot;);        m=new QSqlTableModel();        m-&gt;setTable(&quot;student&quot;);        ui-&gt;tableView-&gt;setModel(m);    &#125;    else    &#123;        QMessageBox::warning(this,&quot;连接提示&quot;,&quot;连接失败&quot;);    &#125;&#125;Widget::~Widget()&#123;    delete ui;&#125;void Widget::on_pushButton_clicked()&#123;    m-&gt;select();&#125;

MediaPlayer+AudioOutput(m_mediaPlayer-&gt;setAudioOutput(m_audioOutput);)获取文件目录QDirIterator，.hasNext()进行遍历播放逻辑

void MusicPlayer::on_musicListView_doubleClicked(const QModelIndex &amp;index)&#123;    auto url=index.data(Qt::UserRole+1).toUrl();    m_mediaPlayer-&gt;setSource(url);    m_mediaPlayer-&gt;play();&#125;

