learned
QFileDialog用于获取需要打开的文件（点击）
QFile::open打开文件，readAll()获取QByteArray类型的数据
键与槽函数Qt::ControlModifier,mousePressEvent，QPoint

if(QKetEvent* k-&gt;modifiers()==Qt::ControlModifier &amp;&amp; k-&gt;key()==Qt::Key_S)        &#123;            saveActionSlot();        &#125;


槽函数的连接（与按键事件）

connect(ui-&gt;newAction,&amp;QAction::triggered,this,&amp;MainWindow::newActionSlot);
code#include &quot;mainwindow.h&quot;#include &quot;./ui_mainwindow.h&quot;#include &lt;QFileDialog&gt;#include &lt;QMessageBox&gt;MainWindow::MainWindow(QWidget *parent)    : QMainWindow(parent)    , ui(new Ui::MainWindow)&#123;    ui-&gt;setupUi(this);    connect(ui-&gt;newAction,&amp;QAction::triggered,this,&amp;MainWindow::newActionSlot);    connect(ui-&gt;openAction,&amp;QAction::triggered,this,&amp;MainWindow::openActionSlot);    connect(ui-&gt;saveAction,&amp;QAction::triggered,this,&amp;MainWindow::saveActionSlot);&#125;MainWindow::~MainWindow()&#123;    delete ui;&#125;void MainWindow::newActionSlot()&#123;    ui-&gt;textEdit-&gt;clear();    this-&gt;setWindowTitle(&quot;新建文本文档.txt&quot;);&#125;void MainWindow::openActionSlot()&#123;    QString fileName = QFileDialog::getOpenFileName(this,&quot;打开&quot;,                                 QCoreApplication::applicationFilePath(),&quot;*.cpp&quot;);    if(fileName.isEmpty())    &#123;        QMessageBox::warning(this,&quot;警告&quot;,&quot;请选择一个文件&quot;);    &#125;    else    &#123;        // qDebug()&lt;&lt;fileName;        QFile file(fileName);        file.open(QIODevice::ReadOnly);        QByteArray ba=file.readAll();        ui-&gt;textEdit-&gt;setText(QString(ba));        file.close();    &#125;&#125;void MainWindow::saveActionSlot()&#123;    QString fileName = QFileDialog::getSaveFileName(this,&quot;保存&quot;,                                                    QCoreApplication::applicationFilePath());    if(fileName.isEmpty())    &#123;        QMessageBox::warning(this,&quot;警告&quot;,&quot;请选择一个文件&quot;);    &#125;    else    &#123;        // qDebug()&lt;&lt;fileName;        QFile file(fileName);        file.open(QIODevice::WriteOnly);        QByteArray ba;        ba.append(qPrintable(ui-&gt;textEdit-&gt;toPlainText()));        file.write(ba);        file.close();    &#125;&#125;void MainWindow::keyPressEvent(QKeyEvent *k)&#123;    if(k-&gt;modifiers()==Qt::ControlModifier &amp;&amp; k-&gt;key()==Qt::Key_S)    &#123;        saveActionSlot();    &#125;    else if(k-&gt;modifiers()==Qt::ControlModifier&amp;&amp;k-&gt;key()==Qt::Key_N)    &#123;        newActionSlot();    &#125;    else if(k-&gt;modifiers()==Qt::ControlModifier&amp;&amp;k-&gt;key()==Qt::Key_O)    &#123;        openActionSlot();    &#125;&#125;void MainWindow::mousePressEvent(QMouseEvent *m)&#123;    QPoint pt = m-&gt;pos();    qDebug()&lt;&lt;pt;    if(m-&gt;button()==Qt::LeftButton)    &#123;        qDebug()&lt;&lt;&quot;左键被按下&quot;;    &#125;    else if(m-&gt;button()==Qt::RightButton)    &#123;        qDebug()&lt;&lt;&quot;右键被按下&quot;;    &#125;&#125;
